package com.smartcoms.hms.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDate;
@Entity public class Patient { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String patientCode; @NotBlank private String fullName; @NotNull private LocalDate dateOfBirth; @NotBlank private String gender; @NotBlank @Pattern(regexp="^[0-9+ -]{7,20}$") private String phone; private String bloodGroup; private String department; private String status="Outpatient"; private String diagnosis;
 public Long getId(){return id;} public String getPatientCode(){return patientCode;} public void setPatientCode(String v){patientCode=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getBloodGroup(){return bloodGroup;} public void setBloodGroup(String v){bloodGroup=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getDiagnosis(){return diagnosis;} public void setDiagnosis(String v){diagnosis=v;}
}
